final entries=[for(final group in catalog.entries)for(final title in group.value)(title: title,category:group.key)];
@override void initState(){super.initState();restore();}
Future<void> restore()async{final p=await SharedPreferences.getInstance();if(!mounted)return;setState((){saved=p.getStringList('saved')?.toSet()??{};read=p.getStringList('read')?.toSet()??{};recent=p.getString('recent');scale=p.getDouble('scale')??1;});}
